var researchTools = new ResearchTools(notebook);

var tools = new[]
{
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    "You are a research assistant. When given a topic, use the SearchWeb tool to find "
    + "information from multiple angles, use SaveNote to record key findings as you go, "
    + "and then provide a comprehensive summary. Search at least 2-3 different queries "
    + "to get a well-rounded view. Always save important findings before summarizing.")
{
    Tools = [.. tools],
};

Console.WriteLine("Research Agent Ready! Enter a topic to research (or 'quit' to exit):");

while (true)
{
    Console.Write("\n> ");
    var topic = Console.ReadLine()?.Trim();

    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine($"\nResearching: {topic}\n");

    var history = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic thoroughly and provide a summary: {topic}"),
    };

    var options = new AgentInvokeOptions
    {
        MaximumIterations = 10,
    };

    try
    {
        await foreach (var message in agent.InvokeStreamingAsync(history, options))
        {
            if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
            {
                Console.Write(message.Text);
            }
        }

        Console.WriteLine();

        if (notebook.Notes.Count > 0)
        {
            Console.WriteLine("\n--- Saved Notes ---");
            foreach (var note in notebook.Notes)
            {
                Console.WriteLine($"• [{note.Category}] {note.Content}");
            }
        }

        notebook.Clear();
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error during research: {ex.Message}");
    }
}

Console.WriteLine("Goodbye!");

// --- Supporting types ---

public sealed class Notebook
{
    private readonly List<Note> _notes = [];
    public IReadOnlyList<Note> Notes => _notes;

    public void Add(string category, string content) =>
        _notes.Add(new Note(category, content, DateTime.UtcNow));

    public void Clear() => _notes.Clear();
}

public sealed record Note(string Category, string Content, DateTime Timestamp);

public sealed class ResearchTools(Notebook notebook)
{
    private static readonly HttpClient Http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information on a query. Returns a summary of search results.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        Console.WriteLine($"  🔍 Searching: {query}");

        try
        {
            // Use a public search-summary API (DuckDuckGo Instant Answer)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await Http.GetStringAsync(url);
            var doc = System.Text.Json.JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            var abstractText = root.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                results.Add($"Summary: {abstractText}");

            var abstractSource = root.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abstractSource))
                results.Add($"Source: {abstractSource}");

            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                var count = 0;
                foreach (var topic in topics.EnumerateArray())
                {
                    if (count >= 5) break;
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.Add($"- {text}");
                        count++;
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n", results)
                : $"No detailed results found for '{query}'. Try a more specific query.";
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note with a category label for later reference.")]
    public string SaveNote(
        [Description("Category for the note (e.g., 'key-fact', 'source', 'insight')")] string category,
        [Description("The content of the note to save")] string content)
    {
        notebook.Add(category, content);
        Console.WriteLine($"  📝 Note saved [{category}]");
        return $"Note saved under '{category}'. Total notes: {notebook.Notes.Count}";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public string GetNotes()
    {
        if (notebook.Notes.Count == 0)
            return "No notes saved yet.";

        var lines = notebook.Notes.Select((n, i) =>
            $"{i + 1}. [{n.Category}] {n.Content}");
        return string.Join("\n", lines);
    }
}

